import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life - Next Generation", () => {
  it.todo("should return no living cells for an empty grid");
  it.todo("should let a single living cell die from underpopulation");
  it.todo("should let two adjacent living cells die from underpopulation");
  it.todo("should let a living cell with 2 live neighbors survive");
  it.todo("should let a living cell with 3 live neighbors survive");
  it.todo("should let a living cell with more than 3 live neighbors die from overpopulation");
  it.todo("should bring a dead cell with exactly 3 live neighbors to life");
  it.todo("should keep a block still life unchanged");
  it.todo("should oscillate a blinker from vertical to horizontal");
  it.todo("should oscillate a blinker from horizontal back to vertical");
  it.todo("should handle cells at negative coordinates");
});
